#!/bin/bash
EQGUARD_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd -P)"
set +e
cd "${EQGUARD_ROOT}"
python3 generate_trans/cec/direct_cec.py --golden "${EQGUARD_ROOT}/generate_trans/hosts_bt2/rs232t1000/rs232t1000__injalpha_d1_s42.v" --candidate "${EQGUARD_ROOT}/generate_trans/keepab_s1_fraig/conv/rs232t1000/rs232t1000__injalpha_d1_s42__keepbnd__ys_abc.v" --vali-dir ${EQGUARD_VALI_DIR:?Set EQGUARD_VALI_DIR to the functional cell library directory} --timeout 900 --log "${EQGUARD_ROOT}/generate_trans/keepab_s1_fraig/logs/cecconv_rs232t1000__injalpha_d1_s42__keepbnd__ys_abc.log" > "${EQGUARD_ROOT}/generate_trans/keepab_s1_fraig/logs/cecconv_rs232t1000__injalpha_d1_s42__keepbnd__ys_abc.txt" 2>&1
python3 generate_trans/cec/direct_cec.py --golden "${EQGUARD_ROOT}/generate_trans/hosts_bt2/rs232t1000/rs232t1000__ctlmatcha_d1_s42.v" --candidate "${EQGUARD_ROOT}/generate_trans/keepab_s1_fraig/conv/rs232t1000/rs232t1000__ctlmatcha_d1_s42__keepbnd__ys_abc.v" --vali-dir ${EQGUARD_VALI_DIR:?Set EQGUARD_VALI_DIR to the functional cell library directory} --timeout 900 --log "${EQGUARD_ROOT}/generate_trans/keepab_s1_fraig/logs/cecconv_rs232t1000__ctlmatcha_d1_s42__keepbnd__ys_abc.log" > "${EQGUARD_ROOT}/generate_trans/keepab_s1_fraig/logs/cecconv_rs232t1000__ctlmatcha_d1_s42__keepbnd__ys_abc.txt" 2>&1
